SendVerificationCodeForLoginMutation:
mutation SendVerificationCodeForLoginMutation($emailAddress: String, $phoneNumber: String, $recaptchaToken: String) {
  sendVerificationCode(
    verificationReason: login
    emailAddress: $emailAddress
    phoneNumber: $phoneNumber
    recaptchaToken: $recaptchaToken
  ) {
    __typename
    status
    errorMessage
  }
}

SignupWithVerificationCodeMutation:
mutation SignupWithVerificationCodeMutation($verificationCode: String, $emailAddress: String, $phoneNumber: String, $birthday: String) {
  signupWithVerificationCode(
    verificationCode: $verificationCode
    emailAddress: $emailAddress
    phoneNumber: $phoneNumber
    birthday: $birthday
  ) {
    __typename
    status
    errorMessage
  }
}

AppleInAppPurchasesUpdatePurchaseMutatio:
mutation AppleInAppPurchasesUpdatePurchaseMutation($transaction: AppleInAppPurchasesTransaction!, $botsPerPage: Int!, $botCursorAfter: String) {
  appleInAppPurchasesUpdatePurchase(transaction: $transaction) {
    __typename
    viewer {
      __typename
      id
      availableBotsConnection(first: $botsPerPage, after: $botCursorAfter) {
        __typename
        edges {
          __typename
          node {
            __typename
            ...BotPreviewFragment
          }
        }
        pageInfo {
          __typename
          hasNextPage
        }
      }
    }
  }
}
fragment BotPreviewFragment on Bot {
  id
  __typename
  isSystemBot
  botId
  deletionState
  model
  nickname
  displayName
  description
  isPrivateBot
  minBuildNumberIos
  shouldHide
  botImageInfo {
    __typename
    ...BotImageInfoFragment
  }
  translatedBotTags
  monthlyActiveUsers
  messageTimeoutSecs
  isApiBot
  limitedAccessType
  baseModelDisplayName
  viewerIsFollower
  providerName
  messageUsageLimit {
    __typename
    id
    ...MessageUsageLimitFragment
  }
  introduction
  viewerIsCreator
  canUserAccessBot
  supportsFileUpload
}
fragment BotImageInfoFragment on BotImageInfo {
  __typename
  localAssetName
  remoteAssetURL: remoteAssetUrl
  assetTypeToUse
}
fragment MessageUsageLimitFragment on MessageLimit {
  id
  __typename
  canSendMessage
  dailyMessageSent
  freeLimit
  freeLimitBalance
  freeLimitResetTime
  totalBalance
  balanceTooltipText
  shouldShowLimitInfoBanner
}

SettingsPageQuery:
query SettingsPageQuery($first: Int, $after: String) {
  viewer {
    __typename
    id
    primaryPhoneNumber
    primaryEmail
    confirmedEmails
    showPoeDebugPanel: booleanGate(gateName: "poe_show_debug_panel")
    ...MessageLimitsConnectionFragment
  }
}
fragment MessageLimitsConnectionFragment on Viewer {
  __typename
  messageLimitsConnection(first: $first, after: $after) {
    __typename
    edges {
      __typename
      node {
        __typename
        ...MessageLimitFragment
      }
    }
    pageInfo {
      __typename
      hasNextPage
    }
  }
}
fragment MessageLimitFragment on MessageLimit {
  __typename
  id
  bot {
    __typename
    displayName
  }
  freeLimit
  freeLimitBalance
  freeLimitResetTime
  messageLimitId
  paidLimit
  paidLimitBalance
  paidLimitResetTime
}
